"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { Paper, type PaperProps } from "@/components/ui/paper"
import { useChatAlign } from "@/lib/chat-align"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { bubbleReactionsRecipe, bubbleRecipe, type BubbleVariant } from "@/lib/ink/recipes/bubble-ink"
import { cn } from "@/lib/utils"

type BubbleShape = "cloud" | "note" | "sticky"
type BubblePen = "ink" | "you"

type BubbleState = { variant: BubbleVariant; align: "start" | "end"; shape: BubbleShape; pen: BubblePen }
const BubbleContext = React.createContext<BubbleState>({ variant: "default", align: "start", shape: "cloud", pen: "ink" })

function BubbleGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="bubble-group"
      className={cn("flex min-w-0 flex-col gap-2 [&>[data-slot=bubble]:not(:last-child)_[data-part=tail]]:hidden", className)}
      {...props}
    />
  )
}

const bubbleVariants = cva(
  "group/bubble relative flex w-fit max-w-[80%] min-w-0 flex-col gap-1 group-data-[align=end]/message:self-end data-[align=end]:self-end data-[variant=ghost]:max-w-full",
  {
    variants: {
      variant: {
        default: "",
        secondary: "",
        muted: "",
        tinted: "",
        outline: "",
        ghost: "",
        destructive: "",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Bubble({
  variant = "default",
  align,
  shape = "cloud",
  pen = "ink",
  tail = true,
  className,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof bubbleVariants> & {
    align?: "start" | "end"
    shape?: BubbleShape
    pen?: BubblePen
    tail?: boolean
  }) {
  const inherited = useChatAlign()
  const a = align ?? inherited ?? "start"
  const v = variant ?? "default"
  const state = React.useMemo<BubbleState>(() => ({ variant: v, align: a, shape, pen }), [v, a, shape, pen])
  return (
    <BubbleContext.Provider value={state}>
      <div
        data-slot="bubble"
        data-variant={v}
        data-align={a}
        data-shape={shape}
        data-tail={tail ? undefined : "false"}
        className={cn(bubbleVariants({ variant: v }), className)}
        {...props}
      />
    </BubbleContext.Provider>
  )
}

const contentVariants = cva(
  "relative isolate w-fit max-w-full min-w-0 px-4 py-2.5 font-hand text-base leading-relaxed wrap-break-word group-data-[align=end]/bubble:self-end compact:px-3.5 compact:py-2 calm:px-3 calm:py-1.5 [&:is(a,button)]:cursor-pointer [&:is(button)]:text-start group-data-[tail=false]/bubble:[&>svg_[data-part=tail]]:hidden",
  {
    variants: {
      variant: {
        default: "text-paper",
        secondary: "text-secondary-foreground",
        muted: "text-foreground",
        tinted: "text-foreground",
        outline: "text-foreground",
        ghost: "rounded-none bg-transparent p-0 text-foreground compact:p-0 calm:p-0",
        destructive: "text-paper",
      },
    },
    defaultVariants: { variant: "default" },
  }
)

const NOTE_STOCK: Record<BubbleVariant, NonNullable<PaperProps["stock"]>> = {
  default: "slip",
  secondary: "index-card",
  muted: "paper",
  tinted: "card",
  outline: "graph",
  ghost: "slip",
  destructive: "slip",
}
const STICKY_STOCK: Record<BubbleVariant, NonNullable<PaperProps["stock"]>> = {
  default: "sticky-orange",
  secondary: "sticky-yellow",
  muted: "sticky-blue",
  tinted: "sticky-pink",
  outline: "sticky-green",
  ghost: "sticky-yellow",
  destructive: "sticky-pink",
}

const CREASES =
  "after:pointer-events-none after:absolute after:inset-0 after:z-0 after:content-[''] after:mix-blend-multiply after:[background:linear-gradient(90deg,transparent_31.6%,rgb(var(--ll-shade)/0.16)_32.2%,color-mix(in_srgb,var(--ll-photo)_50%,transparent)_32.9%,transparent_35.5%,transparent_64%,rgb(var(--ll-shade)/0.12)_64.6%,color-mix(in_srgb,var(--ll-photo)_45%,transparent)_65.3%,transparent_68%)]"

function BubbleContent({
  asChild = false,
  className,
  seed,
  paper,
  ref,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  asChild?: boolean
  seed?: string | number
  paper?: Partial<PaperProps>
}) {
  const { variant, align, shape, pen } = React.useContext(BubbleContext)
  const drawn = shape === "cloud" && variant !== "ghost"
  const interactive = asChild
  const { hostRef, hostProps, node } = useInk({
    recipe: bubbleRecipe,
    params: { variant, tail: align, pen, interactive },
    kind: "bubble",
    seed,
    still: true,
  })
  const merged = useMergedRef<HTMLElement>(drawn ? hostRef : undefined, ref as React.Ref<HTMLElement> | undefined)
  const voice = pen === "you" ? "font-script text-[1.35rem] leading-snug text-ink-you" : undefined
  const base = contentVariants({ variant })

  if (shape !== "cloud") {
    const sticky = shape === "sticky"
    return (
      <Paper
        data-slot="bubble-content"
        ref={merged as React.Ref<HTMLElement>}
        stock={sticky ? STICKY_STOCK[variant] : NOTE_STOCK[variant]}
        curl
        seed={seed}
        className={cn(base, "rounded-none font-script text-[1.35rem] leading-snug text-ink", !sticky && CREASES, voice, className)}
        {...paper}
        {...props}
      >
        {children}
      </Paper>
    )
  }

  const Comp = asChild ? Slot.Root : "div"
  return (
    <Comp
      data-slot="bubble-content"
      ref={merged}
      {...(drawn ? hostProps : {})}
      className={cn(base, voice, className)}
      {...props}
    >
      {asChild ? <Slot.Slottable>{children}</Slot.Slottable> : children}
      {drawn ? node : null}
    </Comp>
  )
}

const bubbleReactionsPlace = cva(
  "absolute z-10 flex min-h-6 w-fit shrink-0 items-center justify-center gap-1 px-2 py-0.5 font-hand text-sm has-[button]:p-0 [&>svg[data-ink]]:[filter:var(--ll-drop-sticker)]",
  {
    variants: {
      side: {
        top: "top-0 -translate-y-3/4",
        bottom: "bottom-0 translate-y-3/4",
      },
      align: {
        start: "start-3",
        end: "end-3",
      },
    },
    defaultVariants: {
      side: "bottom",
      align: "end",
    },
  }
)

function BubbleReactions({
  side = "bottom",
  align = "end",
  seed,
  className,
  ref,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  align?: "start" | "end"
  side?: "top" | "bottom"
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({ recipe: bubbleReactionsRecipe, params: {}, kind: "reactions", seed, still: true })
  return (
    <div
      data-slot="bubble-reactions"
      data-align={align}
      data-side={side}
      ref={useMergedRef<HTMLElement>(hostRef, ref as React.Ref<HTMLElement> | undefined) as React.Ref<HTMLDivElement>}
      {...hostProps}
      className={cn(bubbleReactionsPlace({ side, align }), className)}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

export { BubbleGroup, Bubble, BubbleContent, BubbleReactions }
export type { BubbleShape, BubblePen }

import { bandFill, blobFill, wash } from '@/lib/ink/fills'
import { pillPoly, roundRectPoly, seg } from '@/lib/ink/geom'
import { chain, dashedBox, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import type { Ink } from '@/lib/ink/builder'
import type { Line, PenName, Pt, StrokeOpts } from '@/lib/ink/types'

export const bubbleVariantList = ['default', 'secondary', 'muted', 'tinted', 'outline', 'ghost', 'destructive'] as const
export type BubbleVariant = (typeof bubbleVariantList)[number]

export interface BubbleParams {
  variant: BubbleVariant
  tail: 'start' | 'end'
  pen?: 'ink' | 'you'
  interactive?: boolean
}

export const bubbleRadius = (w: number, h: number): number => clamp(Math.min(w, h) * 0.42, 7, 16)

const TAIL_CORNER = 3.4

function cloudLines(ink: Ink, x: number, y: number, w: number, h: number, left: boolean, cheap: boolean): Line[] {
  const rng = ink.next('cloud')
  const j = () => rng.gauss(0, 0.55)
  const TR: Pt = [x + w + j(), y + j()]
  const BR: Pt = [x + w + j(), y + h + j()]
  const BL: Pt = [x + j(), y + h + j()]
  const TL: Pt = [x + j(), y + j()]
  const t0 = rng.range(0.2, 0.42)
  const S: Pt = [TL[0] + (TR[0] - TL[0]) * t0, TL[1] + (TR[1] - TL[1]) * t0 + j() * 0.4]
  const run = Math.min(w * 0.3, rng.range(8, 20))
  const end: Pt = [S[0] + run, S[1] - rng.range(0.5, 2)]
  const bulge = (len: number) => -clamp(len * rng.range(0.008, 0.024), 0.5, 3.4)
  const c = TAIL_CORNER * 1.15
  const vs: Pt[] = left
    ? [S, TR, BR, [BL[0] + c, BL[1]], [BL[0], BL[1] - c], TL, end]
    : [S, TR, [BR[0], BR[1] - c], [BR[0] - c, BR[1]], BL, TL, end]
  const dist = (a: Pt, b: Pt) => Math.hypot(a[0] - b[0], a[1] - b[1])
  const bows = vs.slice(0, -1).map((v, i) => {
    const n = vs[i + 1]
    const len = dist(v, n)
    return len < c * 2.5 ? 0 : bulge(len)
  })
  const rad = bubbleRadius(w, h)
  const so: StrokeOpts = { speed: 1.02, wobble: 0.85, start: 'pool', end: 'flick', simple: cheap }
  return [{ pts: chain(vs, bows, rad, rng, 12), o: so }]
}

function tailLines(ink: Ink, x: number, y: number, w: number, h: number, left: boolean): { lines: Line[]; wedge: Pt[] } {
  const rng = ink.next('tail')
  const dir = left ? -1 : 1
  const bx = left ? x : x + w
  const by = y + h
  const reach = clamp(h * 0.2, 7, 10.5) + rng.range(-0.5, 1.2)
  const rise = clamp(h * 0.34, 11, 18)
  const a: Pt = [bx - dir * 0.6, by - rise]
  const tip: Pt = [bx + dir * reach, by + rng.range(0.6, 2.2)]
  const b: Pt = [bx - dir * clamp(w * 0.07, 7, 12), by + rng.range(-0.3, 0.9)]
  const so: StrokeOpts = { wobble: 0.6, simple: true, speed: 1.05 }
  const out = seg(a[0], a[1], tip[0], tip[1], dir * rng.range(0.8, 2.2), 6)
  const back = seg(tip[0], tip[1], b[0], b[1], rng.range(-0.5, 0.6), 4)
  return {
    lines: [
      { pts: out, o: { ...so, start: 'soft', end: 'soft' } },
      { pts: back, o: { ...so, start: 'soft', end: 'flick' } },
    ],
    wedge: [a, ...out.slice(1, -1), tip, ...back.slice(1, -1), b, [bx - dir * 2, by - 6]],
  }
}

function fillOf(variant: BubbleVariant): { color: 'ink-you' | 'hi' | 'paper-shade' | null; alpha: number } {
  switch (variant) {
    case 'default':
      return { color: 'ink-you', alpha: 0.96 }
    case 'secondary':
      return { color: 'hi', alpha: 0.82 }
    case 'muted':
      return { color: 'paper-shade', alpha: 0.95 }
    default:
      return { color: null, alpha: 0 }
  }
}

export const bubbleRecipe = defineRecipe<BubbleParams>({
  id: 'bubble',
  kind: 'bubble',
  layers: ['rest', 'hover', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { variant, tail, pen = 'ink', interactive = false }, ctx) {
    ink.lean()
    const left = (tail === 'start') === (ctx.dir === 'ltr')
    const r = bubbleRadius(w, h)
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, w, h, { r }))
    if (ctx.lazyOnly || variant === 'ghost') return

    const felt: PenName = variant === 'destructive' ? 'redfelt' : pen === 'you' ? 'blue' : 'ink'
    const calm = ctx.calm
    const inset = clamp(h * 0.05, 1.6, 2.6)
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    const f = fillOf(variant)
    const color = f.color

    ink.layer('rest', () => {
      if (variant === 'outline' || variant === 'tinted' || variant === 'destructive') ink.poly('under', body, 'slip', 0.94)
      if (color) {
        ink.part('fill', () => {
          if (color === 'paper-shade') return wash(ink, body, color, { alpha: 0.95, material: 'wash' })
          if (calm) return wash(ink, body, color, { alpha: 0.6, material: 'wash' })
          const mis = clamp(h * 0.04, 1.4, 3)
          if (h < 30) return blobFill(ink, body, color, { alpha: f.alpha, mis })
          return bandFill(ink, body, color, { alpha: f.alpha, passes: variant === 'default' ? 2 : 1, mis, W: clamp(h * 0.2, 6.5, 9.5), ends: 'loose', overlap: 0.3 })
        })
      } else if (variant === 'tinted') {
        ink.part('fill', () => wash(ink, body, 'marker', { alpha: calm ? 0.24 : 0.3, material: 'wash' }))
      } else if (variant === 'destructive') {
        ink.part('fill', () => blobFill(ink, body, 'red', { alpha: 0.97 }))
      }
      const o: StrokeOpts = variant === 'muted' || calm ? { alpha: 0.85 } : {}
      ink.lines(cloudLines(ink, 0, 0, w, h, left, ctx.tier === 'lo'), calm ? 'pencil.fine' : variant === 'muted' ? `${felt}.fine` as PenName : felt, o)
      ink.part(
        'tail',
        () => {
          const t = tailLines(ink, 0, 0, w, h, left)
          const pale = calm ? 'wash' : 'felt'
          if (color === 'paper-shade') wash(ink, t.wedge, color, { alpha: 0.95, inset: 0, material: pale })
          else if (color && calm) wash(ink, t.wedge, color, { alpha: 0.6, inset: 0, material: 'wash' })
          else if (color) blobFill(ink, t.wedge, color, { alpha: f.alpha, mis: 1 })
          else if (variant === 'tinted') wash(ink, t.wedge, 'marker', { alpha: 0.3, inset: 0, material: pale })
          else if (variant === 'outline' || variant === 'destructive') ink.poly(calm ? 'under' : 'felt', t.wedge, 'slip', 0.94)
          ink.lines(t.lines, calm ? 'pencil.fine' : felt, o)
        },
        'top',
      )
    })

    if (interactive) {
      ink.layer('hover', () => {
        if (calm) return
        const d = 3.6
        ink.lines(
          [
            { pts: seg(r + d + 2, h + d, w + d - 1, h + d, 0.5, 6), o: { start: 'soft', end: 'flick' } },
            { pts: seg(w + d, r + d + 2, w + d, h + d - 1, 0.4, 4), o: { start: 'soft', end: 'flick' } },
          ],
          'ink.fine',
          { width: 1.35 },
        )
      })
    }
  },
})

export interface BubbleReactionsParams {
  dashed?: boolean
}

export const bubbleReactionsRecipe = defineRecipe<BubbleReactionsParams>({
  id: 'bubble-reactions',
  kind: 'reactions',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }, { dashed }, ctx) {
    const body = pillPoly(0.8, 0.8, w - 1.6, h - 1.6)
    ink.layer('rest', () => {
      ink.poly('under', body, 'photo', 1)
      if (dashed) dashedBox(ink, 2.5, 2.5, w - 5, h - 5, { r: (h - 5) / 2, pen: 'pencil', opts: { alpha: 0.55 } })
      const d = pillPoly(0.4, 0.4, w - 0.8, h - 0.8)
      ink.lines([{ pts: [...d, d[1]], o: { simple: true, wobble: ctx.calm ? 0.2 : 0.5, alpha: 0.7, width: 0.9 } }], 'pencil.fine')
    })
  },
})
